package br.com.lealinfo.vidraceiro;
import android.content.*;import android.os.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import java.util.concurrent.*;
/** Durable optimistic outbox. All business/store mutations stay on the Activity main thread. */
final class SyncCoordinator {
 final MainActivity a;final ProfessionalStore store;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();final AtomicFile stateFile;JSONObject state;boolean busy,closed;SyncTransport.Exchange transport=SyncTransport.HTTPS;
 static final String[] ENTITIES={"clients","suppliers","materials","projects"};
 SyncCoordinator(MainActivity a,ProfessionalStore store)throws Exception{this.a=a;this.store=store;stateFile=new AtomicFile(new File(a.getFilesDir(),"pdv-sync-state.json"));state=stateFile.getBaseFile().exists()||new File(stateFile.getBaseFile()+".bak").exists()?new JSONObject(new String(stateFile.readFully(),StandardCharsets.UTF_8)):new JSONObject().put("links",new JSONObject()).put("tenant","");main.postDelayed(this::tick,1200);}
 void save()throws Exception{byte[] b=state.toString().getBytes(StandardCharsets.UTF_8);FileOutputStream out=null;try{out=stateFile.startWrite();out.write(b);stateFile.finishWrite(out);}catch(Exception e){if(out!=null)stateFile.failWrite(out);throw e;}}
 JSONObject links()throws Exception{return state.getJSONObject("links");}
 JSONObject link(String entity,String id)throws Exception{String key=entity+"/"+id;JSONObject l=links().optJSONObject(key);if(l==null){l=new JSONObject().put("revision",0).put("baseline",JSONObject.NULL);links().put(key,l);}return l;}
 static JSONObject business(String entity,JSONObject src)throws Exception{JSONObject p=new JSONObject(src.toString());for(String key:new String[]{"id","pdvId","syncState","revision","createdAt","updatedAt","legacySource","_sync"})p.remove(key);if(entity.equals("clients")||entity.equals("suppliers")){JSONObject clean=new JSONObject();for(String key:new String[]{"name","document","phone","email","address","cep","street","number","complement","district","city","uf"})if(p.has(key))clean.put(key,p.optString(key));return clean;}if(entity.equals("projects")){JSONObject budget=p.optJSONObject("budget");if(budget!=null)for(String k:new String[]{"price","service","discount","extra"})if(budget.has(k))budget.put(k,Commercial.amount(budget.optString(k)).stripTrailingZeros().toPlainString());}return p;}
 static String canonical(Object o)throws Exception{if(o instanceof JSONObject){JSONObject j=(JSONObject)o;ArrayList<String> keys=new ArrayList<>();j.keys().forEachRemaining(keys::add);Collections.sort(keys);StringBuilder b=new StringBuilder("{");for(String k:keys)b.append(JSONObject.quote(k)).append(':').append(canonical(j.get(k))).append(',');return b.append('}').toString();}if(o instanceof JSONArray){StringBuilder b=new StringBuilder("[");JSONArray ar=(JSONArray)o;for(int i=0;i<ar.length();i++)b.append(canonical(ar.get(i))).append(',');return b.append(']').toString();}return o instanceof String?JSONObject.quote((String)o):String.valueOf(o);}
 static boolean equal(JSONObject a,JSONObject b)throws Exception{return a!=null&&b!=null&&canonical(a).equals(canonical(b));}
 String status(){String tenant=state.optString("tenant");if(tenant.isEmpty())return "PDV NÃO CONECTADO\nConecte uma vez usando o código mostrado no computador.";int pending=0,conflicts=0;JSONObject links=state.optJSONObject("links");if(links!=null){Iterator<String> it=links.keys();while(it.hasNext()){JSONObject l=links.optJSONObject(it.next());if(l.has("pending"))pending++;if(l.has("conflict"))conflicts++;}}String date=state.optLong("lastSuccess")==0?"Ainda não realizada":new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm:ss",new Locale("pt","BR")).format(new Date(state.optLong("lastSuccess")));long pdvSeen=state.optLong("pdvLastSeen");return "PDV: "+state.optString("name","Conectado")+"\n"+(busy?"SINCRONIZANDO":state.optString("error").isEmpty()?"CONEXÃO AUTORIZADA":"OFFLINE / SINCRONIZAÇÃO PENDENTE")+"\nÚltima sincronização: "+date+"\nPendentes: "+pending+" • Conflitos: "+conflicts+"\n"+(pdvSeen>0?"Último contato do PDV: "+new java.text.SimpleDateFormat("dd/MM HH:mm",new Locale("pt","BR")).format(new Date(pdvSeen)):"Aguardando primeiro contato do PDV.")+(state.optBoolean("photoPending")?"\nAnexo pendente de transferência.":"")+(state.optString("error").isEmpty()?"":"\n"+state.optString("error"));}
 void notifyUi(){if(a.syncRefresh!=null)a.syncRefresh.run();}
 void connect(String code){if(busy)return;busy=true;notifyUi();worker.execute(()->{try{SyncTransport.register();JSONObject result=transport.call("/sync/pair",new JSONObject().put("code",code.trim().replace(" ","").toUpperCase(Locale.ROOT)));main.post(()->{if(closed)return;try{String old=state.optString("tenant"),tenant=result.getString("tenant");if(!old.isEmpty()&&!old.equals(tenant))throw new IOException("Outro PDV já está vinculado. Dados locais preservados.");state.put("tenant",tenant).put("name",result.optString("name")).put("error","");save();busy=false;notifyUi();tick();}catch(Exception e){failed(e);}});}catch(Exception e){main.post(()->{if(!closed)failed(e);});}});}
 void failed(Exception e){busy=false;try{state.put("error",e.getMessage()==null?"Conexão indisponível; dados preservados.":e.getMessage());save();}catch(Exception ignored){}notifyUi();}
 void tick(){if(closed)return;main.removeCallbacksAndMessages(null);main.postDelayed(this::tick,30000);if(busy||state.optString("tenant").isEmpty())return;try{a.flush();JSONArray changes=prepare();busy=true;notifyUi();worker.execute(()->exchange(changes,null));}catch(Exception e){failed(e);}}
 JSONArray prepare()throws Exception{JSONArray out=new JSONArray();int bytes=0;for(String entity:ENTITIES){if(entity.equals("materials"))continue;JSONArray list=store.list(entity);for(int i=0;i<list.length();i++){JSONObject local=list.getJSONObject(i);JSONObject l=link(entity,local.getString("id")),payload=business(entity,local);if(l.has("conflict"))continue;if(entity.equals("projects")){try{a.validateProject(local);}catch(Exception invalid){continue;}}
  if(entity.equals("projects")){JSONArray drafts=new JSONArray(),ids=local.optJSONArray("materialLocalIds");for(int j=0;ids!=null&&j<ids.length();j++){JSONObject m=store.find("materials",ids.optString(j));if(m!=null&&m.isNull("pdvId"))drafts.put(new JSONObject().put("id",m.getString("id")).put("name",m.optString("name")).put("specification",m.optString("specification")));}if(drafts.length()>0)payload.put("materialDrafts",drafts);}JSONObject base=l.optJSONObject("baseline"),pending=l.optJSONObject("pending");if(pending==null&&!equal(base,payload)){pending=new JSONObject().put("entity",entity).put("id",local.getString("id")).put("operationId",UUID.randomUUID().toString()).put("baseRevision",l.optLong("revision")).put("payload",payload);l.put("pending",pending);}
  if(pending!=null&&out.length()<20&&bytes+pending.toString().length()<3000000){out.put(new JSONObject(pending.toString()));bytes+=pending.toString().length();}
 }}save();return out;}
 void exchange(JSONArray changes,String cursor){try{JSONObject response=transport.call("/sync/exchange",new JSONObject().put("changes",changes).put("cursor",cursor==null?JSONObject.NULL:cursor));main.post(()->{if(closed)return;try{if(!state.getString("tenant").equals(response.getString("tenant")))throw new IOException("Resposta de outro PDV recusada.");apply(response);String next=response.optString("cursor","");if(!next.isEmpty()&&!next.equals("null")){worker.execute(()->exchange(new JSONArray(),next));return;}state.put("lastSuccess",System.currentTimeMillis()).put("pdvLastSeen",response.optLong("pdvLastSeen")).put("error","");store.save();save();busy=false;notifyUi();photos();}catch(Exception e){failed(e);}});}catch(Exception e){main.post(()->{if(!closed)failed(e);});}}
 void apply(JSONObject response)throws Exception{JSONArray results=response.optJSONArray("results");for(int i=0;results!=null&&i<results.length();i++){JSONObject result=results.getJSONObject(i);String entity=result.optString("entity"),id=result.optString("id");JSONObject l=link(entity,id);if(result.optBoolean("ok")){JSONObject rec=result.getJSONObject("record");l.put("baseline",new JSONObject(rec.getJSONObject("payload").toString())).put("revision",rec.getLong("revision"));l.remove("pending");l.remove("error");JSONObject local=store.find(entity,id);if(local!=null){local.put("pdvId",rec.opt("officialId")).put("syncState","SYNCHRONIZED");}}else if(result.optBoolean("conflict")){l.put("conflict",result.opt("record"));}else l.put("error",result.optString("error","Dados pendentes de revisão."));}
 JSONArray records=response.optJSONArray("records");for(int i=0;records!=null&&i<records.length();i++){JSONObject rec=records.getJSONObject(i);String entity=rec.getString("entity"),id=rec.getString("id");if(!Arrays.asList(ENTITIES).contains(entity))continue;JSONObject l=link(entity,id),local=store.find(entity,id),remote=rec.getJSONObject("payload");if(rec.getLong("revision")<=l.optLong("revision"))continue;JSONObject base=l.optJSONObject("baseline");if(local!=null&&!equal(business(entity,local),base)&&!equal(business(entity,local),remote)){l.put("conflict",rec);continue;}if(local==null){local=new JSONObject().put("id",id);store.list(entity).put(local);}replace(local,remote,entity,id,rec.opt("officialId"));l.put("baseline",new JSONObject(remote.toString())).put("revision",rec.getLong("revision"));l.remove("pending");l.remove("conflict");}
 store.save();save();notifyUi();}
 static void replace(JSONObject local,JSONObject payload,String entity,String id,Object official)throws Exception{ArrayList<String> keys=new ArrayList<>();local.keys().forEachRemaining(keys::add);for(String k:keys)if(!Arrays.asList("id","pdvId","syncState","revision","createdAt","updatedAt").contains(k))local.remove(k);Iterator<String> it=payload.keys();while(it.hasNext()){String key=it.next();local.put(key,payload.get(key));}local.put("id",id).put("pdvId",official==null?JSONObject.NULL:official).put("syncState","SYNCHRONIZED");}
 void conflicts(){try{ArrayList<String> ids=new ArrayList<>(),names=new ArrayList<>();Iterator<String> it=links().keys();while(it.hasNext()){String k=it.next();JSONObject l=links().getJSONObject(k);if(l.has("conflict")&&!l.isNull("conflict")){ids.add(k);JSONObject r=l.getJSONObject("conflict");names.add(r.getJSONObject("payload").optString("name",r.getJSONObject("payload").optString("title",k)));}}if(ids.isEmpty()){a.message("Nenhum conflito pendente.\n"+status());return;}new InteriorVisuals.Dialog(a).setTitle("Revisar alterações concorrentes").setItems(names.toArray(new String[0]),(d,n)->{String k=ids.get(n);a.run(()->{JSONObject l=links().getJSONObject(k),rec=l.getJSONObject("conflict");String[] parts=k.split("/",2);JSONObject local=store.find(parts[0],parts[1]);new InteriorVisuals.Dialog(a).setTitle(names.get(n)).setMessage("As duas versões foram preservadas. Escolha explicitamente qual deve continuar.\n\nLOCAL:\n"+business(parts[0],local).toString(2)+"\n\nPDV/SERVIDOR:\n"+rec.getJSONObject("payload").toString(2)).setPositiveButton("MANTER LOCAL",(x,w)->a.run(()->resolve(k,false))).setNeutralButton("USAR SERVIDOR",(x,w)->a.run(()->resolve(k,true))).setNegativeButton("VOLTAR",null).show();});}).show();}catch(Exception e){a.message(e.getMessage());}}
 void resolve(String key,boolean useRemote)throws Exception{JSONObject l=links().getJSONObject(key),rec=l.getJSONObject("conflict");String[] p=key.split("/",2);JSONObject local=store.find(p[0],p[1]);JSONArray archive=state.optJSONArray("conflictArchive");if(archive==null){archive=new JSONArray();state.put("conflictArchive",archive);}archive.put(new JSONObject().put("at",System.currentTimeMillis()).put("entity",p[0]).put("id",p[1]).put("local",business(p[0],local)).put("remote",rec));if(useRemote)replace(local,rec.getJSONObject("payload"),p[0],p[1],rec.opt("officialId"));l.put("baseline",rec.getJSONObject("payload")).put("revision",rec.getLong("revision"));l.remove("pending");l.remove("conflict");store.save();save();notifyUi();tick();}
 void photos(){ArrayList<JSONObject> tasks=new ArrayList<>();try{JSONArray p=store.list("projects");for(int i=0;i<p.length();i++){JSONObject project=p.getJSONObject(i),manifest=project.optJSONObject("photoAttachment");if(manifest==null)continue;JSONObject l=link("projects",project.getString("id"));if(l.optLong("revision")==0||l.has("conflict"))continue;String sha=manifest.optString("sha256");if(sha.equals(l.optString("photoDone")))continue;tasks.add(new JSONObject().put("id",project.getString("id")).put("manifest",new JSONObject(manifest.toString())));}}catch(Exception e){return;}if(tasks.isEmpty())return;worker.execute(()->{for(JSONObject task:tasks){try{String id=task.getString("id");JSONObject m=task.getJSONObject("manifest");String sha=m.getString("sha256");File photo=new File(a.getFilesDir(),"images/"+id+"/photo.jpg");boolean local=photo.exists()&&SecureGateway.hash(Files.readAllBytes(photo.toPath())).equals(sha);JSONObject cap=transport.call(local?"/sync/photo-put":"/sync/photo-get",new JSONObject().put("projectId",id).put("sha256",sha).put("size",m.getLong("sizeBytes")));byte[] bytes=local?Files.readAllBytes(photo.toPath()):transport.download(cap.getString("url"));if(bytes.length!=m.getLong("sizeBytes")||!SecureGateway.hash(bytes).equals(sha))throw new IOException("Hash da foto não confere.");if(local)transport.upload(cap.getString("url"),bytes);final boolean hadLocal=local;main.post(()->{if(closed)return;try{JSONObject target=store.find("projects",id);if(target==null||!sha.equals(target.optJSONObject("photoAttachment").optString("sha256")))return;if(!hadLocal){AtomicFile file=new AtomicFile(new File(PhotoAttachment.directory(a,target),"photo.jpg"));FileOutputStream out=null;try{out=file.startWrite();out.write(bytes);file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}link("projects",id).put("photoDone",sha);state.put("photoPending",false);save();notifyUi();}catch(Exception ignored){}});}catch(Exception e){main.post(()->{if(closed)return;try{state.put("photoPending",true);save();}catch(Exception ignored){}notifyUi();});}}});}
 void close(){closed=true;main.removeCallbacksAndMessages(null);worker.shutdown();}
}
